\set ON_ERROR_STOP on
BEGIN;
-- Bounded full-run checkpoints. No document contents, tokens or detail tables.
-- UUID is generated by the application; user deletion cascades, KVKK export includes this table.
CREATE TABLE IF NOT EXISTS office_uyap_audit_runs (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  revision INTEGER NOT NULL CHECK (revision > 0),
  finished BOOLEAN NOT NULL DEFAULT false,
  snapshot JSONB NOT NULL CHECK (jsonb_typeof(snapshot) = 'object' AND octet_length(snapshot::text) <= 2000000),
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS idx_office_uyap_audit_runs_owner ON office_uyap_audit_runs(owner_id, created_at DESC);
ALTER TABLE office_uyap_audit_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE office_uyap_audit_runs FORCE ROW LEVEL SECURITY;
CREATE POLICY office_uyap_audit_runs_select ON office_uyap_audit_runs FOR SELECT USING (owner_id=app_current_user_id());
CREATE POLICY office_uyap_audit_runs_insert ON office_uyap_audit_runs FOR INSERT WITH CHECK (owner_id=app_current_user_id());
CREATE POLICY office_uyap_audit_runs_update ON office_uyap_audit_runs FOR UPDATE
  USING (owner_id=app_current_user_id()) WITH CHECK (owner_id=app_current_user_id());
CREATE POLICY office_uyap_audit_runs_delete ON office_uyap_audit_runs FOR DELETE USING (owner_id=app_current_user_id());
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='nhr_runtime') THEN
    GRANT SELECT, INSERT, UPDATE, DELETE ON office_uyap_audit_runs TO nhr_runtime;
  END IF;
END $$;
COMMIT;
